#include <iostream>

int main() {
    long long m = 0, n = 0;
    if (!(std::cin >> m >> n)) return 0;

    // 1. Russian Peasant Multiplication using while loop
    long long a = m, b = n;
    long long product = 0;
    while (a > 0) {
        if (a % 2 != 0) {
            product += b;
        }
        a >>= 1;
        b <<= 1;
    }
    std::cout << m << " * " << n << " = " << product << "\n";

    // 2. Classical puzzle: chickens (g) and dogs (c)
    int g = 0;
    while (g <= 36) {
        int c = 0;
        while (c <= 50) {
            if (g + c == 36 && 2 * g + 4 * c == 100) {
                std::cout << "Ga: " << g << ", Cho: " << c << "\n";
            }
            ++c;
        }
        ++g;
    }

    return 0;
}

#include <iostream>
#include <cmath>
#include <iomanip>

int gcd_subtraction(int m, int n) {
    if (m < n) {
        int t = m; m = n; n = t;
    }
    while (m != n) {
        int r = m - n;
        if (r > n) {
            m = r;
        } else {
            m = n;
            n = r;
        }
    }
    return m;
}

int main() {
    int m = 0, n = 0;
    if (!(std::cin >> m >> n)) return 0;

    std::cout << "UCLN = " << gcd_subtraction(m, n) << "\n";

    // Bisection method for f(x) = exp(x) - 1.5 on [0, 1]
    double a = 0.0, b = 1.0, c = 0.0;
    while ((b - a) > 1.0e-6) {
        c = (a + b) / 2.0;
        double fa = std::exp(a) - 1.5;
        double fc = std::exp(c) - 1.5;
        if (fc == 0.0) break;
        if (fa * fc > 0.0) {
            a = c;
        } else {
            b = c;
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << "Nghiem xap xi cua phuong trinh = " << c << "\n";
    return 0;
}

#include <iostream>
#include <cmath>
#include <iomanip>

int main() {
    int n = 1;
    double S = 0.0;
    double term = 0.0;
    const double epsilon = 1.0e-6;

    // Using do...while: body runs at least once
    do {
        term = 1.0 / (static_cast<double>(n) * n);
        S += term;
        ++n;
    } while (term >= epsilon);

    double pi = std::sqrt(6.0 * S);
    std::cout << std::fixed << std::setprecision(5);
    std::cout << "pi = " << pi << "\n";

    return 0;
}
